(function(){
'use strict';
const D=window.FLIGHT_DATA,C=window.AirlineCore;
const $=(id)=>document.getElementById(id);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=(x)=>esc(x), euro=(n)=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const codeName=(code)=>D.airports.find(a=>a.code===code)?.name||code;
const operatorName=(id)=>D.airlines.find(a=>a.id===id)?.name||id;
const hasOtherOperators=(it)=>Boolean(it?.legs?.some(l=>!['ML','MC'].includes(l.carrier)));
const bookingHasOtherOperators=()=>[STATE.booking.out,STATE.booking.back].some(hasOtherOperators);
const country=(code)=>D.airports.find(a=>a.code===code)?.country||'';
const routeLabel=(code)=>`${codeName(code)} (${code})`;
const getStored=(key,fall)=>{try{return JSON.parse(localStorage.getItem(key))??fall}catch{return fall}};
const save=(key,v)=>{try{localStorage.setItem(key,JSON.stringify(v))}catch{}};
const bookings=()=>getStored('molliair-reservations-v2',[]);
const STATE={
 form:{from:'MOL',to:'MIA',dateOut:'2027-05-14',dateIn:'2027-05-21',trip:'round',adults:1,children:0,infants:0},
 widget:'book',popup:false,sort:'recommended',connectionFilter:'all',airlineScope:'all',
 booking:{out:null,back:null,fare:'CLASSIC',people:[],email:'',phone:'',extras:{bags:0,seats:0,meals:0,priority:false},selectedSeats:[],agree:false},
 resultPhase:'out',seatOpen:true,managed:null,checkinBooking:null,networkYear:2027,networkAirport:'MOL',networkAirline:'ARG',destinationRegion:'all'
};
const NAV={home:'Startseite',booking:'Flüge buchen',results:'Flugauswahl',fares:'Tarif wählen',passengers:'Reisende',extras:'Zusatzleistungen',review:'Reiseübersicht',success:'Reiseplan gespeichert',destinations:'Reiseziele',offers:'Angebote',destination:'Reiseziel',manage:'Meine Buchung',checkin:'Online Check-in',status:'Flugstatus',baggage:'Gepäck & Tarife',experience:'An Bord',city:'Molliair City',fleet:'Unsere Flotte',club:'Molliair Club',about:'Über Molliair',news:'Neuigkeiten',help:'Hilfe & Kontakt',network:'Streckennetz',legal:'Rechtliches'};
const ROUTE=()=>{let x=location.hash.replace(/^#\/?/,'').split('/');return {page:x[0]||'home',param:x[1]||''}};
function go(page,param=''){const h='#/'+page+(param?'/'+param:'');if(location.hash===h){render();window.scrollTo(0,0)}else location.hash=h}
function showToast(s){let el=$('toast');el.textContent=s;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),3600)}
function icon(name){const paths={plane:'<path d="M21 3 3 11l7 3 3 7 8-18Z"/><path d="m10 14 4-4"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14M13 5l7 7-7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',ticket:'<path d="M2 8a2 2 0 0 0 0 4v4a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-4a2 2 0 0 0 0-4V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2Z"/><path d="M13 6v2m0 4v2m0 4v1"/>',bag:'<rect x="5" y="8" width="14" height="13" rx="2"/><path d="M9 8V5a3 3 0 0 1 6 0v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',seat:'<path d="M7 2v10a4 4 0 0 0 4 4h6M7 21v-4m-3-1h16v5M17 16V8a2 2 0 0 0-4 0v5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 5-6 13 0 18m0-18c6 5 6 13 0 18"/>',heart:'<path d="M20.8 4.6c-1.9-2-5.1-2-7 0L12 6.4l-1.8-1.8c-2-2-5.2-2-7.2 0s-2 5.2 0 7.2L12 21l8.8-9.2c2-2 2-5.2 0-7.2Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',swap:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',star:'<path d="m12 2 3.1 6.3L22 9.3l-5 4.9 1.2 6.8L12 17.8 5.8 21 7 14.2 2 9.3l6.9-1Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>'};return `<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.plane}</svg></span>`}
function button(text,href,kind='lime',extra=''){return `<a href="${href}" class="btn btn-${kind} ${extra}">${text}</a>`}
function pageHero(title,subtitle='',dark=false){return `<div class="page-hero ${dark?'dark':''}"><div class="container"><div class="bread"><a href="#/home">Startseite</a> <span>›</span> ${E(title)}</div><h1>${E(title)}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div></div>`}
function sectionHeading(kicker,title,description='',more=''){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2 style="margin-top:8px">${title}</h2>${description?`<p>${description}</p>`:''}</div>${more?`<a class="link small" href="${more}">Alle entdecken ${icon('arrow')}</a>`:''}</div>`}
function airportOptions(sel){return D.airports.slice().sort((a,b)=>a.name.localeCompare(b.name,'de')).map(a=>`<option value="${a.code}" ${sel===a.code?'selected':''}>${E(a.name)} (${a.code}) · ${E(a.country)}</option>`).join('')}
function passengerText(){const f=STATE.form;let n=f.adults+f.children+f.infants;return `${n} ${n===1?'Reisender':'Reisende'} · Economy`}
function searchWidget(home=false){const f=STATE.form;const tabs=[['book','Flug buchen','plane'],['manage','Meine Buchung','ticket'],['checkin','Check-in','check'],['status','Flugstatus','clock']];return `<div class="booking-shell"><div class="booking-tabs">${tabs.map(t=>`<button type="button" data-action="widget-tab" data-tab="${t[0]}" class="${STATE.widget===t[0]?'active':''}">${icon(t[2])}${t[1]}</button>`).join('')}</div><div class="booking-main">${STATE.widget==='book'?`<form id="flightSearchForm"><div class="trip-options"><label><input type="radio" name="trip" value="round" ${f.trip==='round'?'checked':''}> Hin- und Rückflug</label><label><input type="radio" name="trip" value="one" ${f.trip==='one'?'checked':''}> Nur Hinflug</label><span class="spacer"></span><a href="#/destinations" class="small link">Alle Flugziele</a></div><div class="booking-fields"><div class="field origin-field"><label for="from-select">Von</label><select id="from-select" name="from">${airportOptions(f.from)}</select></div><button class="swap-button" type="button" data-action="swap" aria-label="Start und Ziel tauschen">${icon('swap')}</button><div class="field destination-field"><label for="to-select">Nach</label><select id="to-select" name="to">${airportOptions(f.to)}</select></div><div class="field date-field"><label for="date-out">Hinflug</label><input id="date-out" name="dateOut" type="date" required min="2026-11-23" max="2027-10-31" value="${E(f.dateOut)}"></div><div class="field date-field"><label for="date-in">Rückflug</label><input id="date-in" name="dateIn" type="date" min="2026-11-23" max="2027-10-31" value="${E(f.dateIn)}" ${f.trip==='one'?'disabled':''}></div><div class="field pax-field"><label for="pass-trigger">Reisende</label><button id="pass-trigger" data-action="passengers-pop" class="field-button" type="button" style="width:100%;height:55px;padding:0 13px;border:1px solid #d8e1e7;background:white;border-radius:11px;text-align:left;font-size:13px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${E(passengerText())} <span style="float:right">⌄</span></button>${STATE.popup?renderPassengerPopup():''}</div><div class="field-submit"><button class="btn btn-lime btn-full" type="submit">Flüge suchen ${icon('arrow')}</button></div></div></form><div class="booking-subline"><span>${icon('check')} Direktflüge und Verbindungen mit Umstieg</span><span>Flüge von Molliair, Molliair City und weiteren Airlines</span></div>`:STATE.widget==='manage'?`<form id="widgetLookup" data-kind="manage"><div class="booking-fields lookup-fields"><div class="field"><label>Buchungscode</label><input name="pnr" placeholder="z. B. ML4X7K" required></div><div class="field"><label>Nachname</label><input name="last" placeholder="Nachname" required></div><div class="field-submit" ><button type="submit" class="btn btn-lime btn-full">Buchung öffnen</button></div></div></form>`:STATE.widget==='checkin'?`<form id="widgetLookup" data-kind="checkin"><div class="booking-fields lookup-fields"><div class="field"><label>Buchungscode</label><input name="pnr" placeholder="Buchungscode" required></div><div class="field"><label>Nachname</label><input name="last" placeholder="Nachname" required></div><div class="field-submit" ><button type="submit" class="btn btn-lime btn-full">Check-in öffnen</button></div></div></form>`:`<form id="statusQuickForm"><div class="booking-fields lookup-fields"><div class="field"><label>Flugnummer</label><input name="flightno" placeholder="z. B. ML123" required></div><div class="field"><label>Flugdatum</label><input name="date" type="date" value="${E(f.dateOut)}"></div><div class="field-submit" ><button class="btn btn-lime btn-full" type="submit">Flug finden</button></div></div></form>`}</div></div>`}
function renderPassengerPopup(){const a=STATE.form;return `<div class="passengers-pop"><strong>Wer fliegt mit?</strong>${[['adults','Erwachsene','ab 16 Jahren'],['children','Kinder','2–15 Jahre'],['infants','Kleinkinder','unter 2 Jahren']].map(([k,title,sub])=>`<div class="passenger-row"><div><b class="small">${title}</b><div class="muted tiny">${sub}</div></div><div class="counter"><button data-action="counter" data-counter="${k}" data-delta="-1" type="button" aria-label="Weniger ${title}">−</button><strong>${a[k]}</strong><button data-action="counter" data-counter="${k}" data-delta="1" type="button" aria-label="Mehr ${title}">+</button></div></div>`).join('')}<button class="btn btn-dark btn-full" type="button" data-action="close-passengers">Übernehmen</button></div>`}
function featureHero(){return `<section class="hero"><img class="hero-aircraft" src="aircraft.svg" alt="" aria-hidden="true"><div class="container hero-inner"><span class="hero-kicker">MOLLIAIR · YOUR WORLD, CLOSER</span><h1>Die Welt wartet.<br><span>Du entscheidest wohin.</span></h1><p>Von Mollicity in die Welt: Entdecke besondere Reiseziele, clevere Verbindungen und ein Flugerlebnis, das sich richtig anfühlt.</p><div class="hero-links">${button('Reiseziele entdecken','#/destinations','lime')} ${button('Mehr über Molliair','#/about','white')}</div><div class="hero-small"><span><span class="check">✓</span> Persönlich unterwegs</span><span><span class="check">✓</span> Verbunden über Mollicity</span></div></div></section>`}
const OFFERS=[{code:'STC',from:85,class:'dest-stc',tag:'Stadt erleben',sub:'Stachelland'},{code:'MIA',from:239,class:'dest-mia',tag:'Entdecke Amerika',sub:'USA'},{code:'MST',from:77,class:'dest-mst',tag:'Neu im Sommer 2027',sub:'Mialand'},{code:'TNR',from:162,class:'dest-tnr',tag:'Natur erleben',sub:'Madagaskar'},{code:'BEL',from:189,class:'dest-bel',tag:'Für Entdecker',sub:'Brasilien'},{code:'MBG',from:54,class:'dest-mbg',tag:'Ganz nah',sub:'Molliland'},{code:'GEO',from:179,class:'dest-geo',tag:'Ab 2030 geplant',sub:'Guyana'},{code:'PTY',from:179,class:'dest-pty',tag:'Ab 2030 geplant',sub:'Panama'}];
function offerCards(offers=OFFERS.slice(0,4)){return `<div class="destination-grid">${offers.map(x=>`<a href="#/destination/${x.code}" class="destination-card ${x.class}"><span class="over">${x.tag}</span><div class="detail"><h3>${E(codeName(x.code))}</h3><p>${E(x.sub)}</p><div class="dprice"><span>Hinflug ab</span><strong>${euro(x.from)}</strong></div></div></a>`).join('')}</div>`}
function renderHome(){return featureHero()+`<div class="container home-search-wrap">${searchWidget(true)}<div class="quick-grid">${[['manage','Meine Buchung','Deine Reise im Blick','ticket'],['checkin','Online Check-in','Bequem von zu Hause','check'],['status','Flugstatus','Abflüge & Ankünfte','clock'],['baggage','Gepäck & Tarife','Alles Wichtige zum Flug','bag']].map(x=>`<a class="quick-item" href="#/${x[0]}"><div class="quick-icon">${icon(x[3])}</div><div><strong>${x[1]}</strong><small>${x[2]}</small></div><span class="item-arrow">›</span></a>`).join('')}</div></div><section class="section"><div class="container">${sectionHeading('Deine Reise beginnt hier','Wohin zieht es dich als Nächstes?','Entdecke unsere beliebtesten Flugziele. Ob Wochenendtrip oder große Reise – dein nächstes Abenteuer ist nur wenige Klicks entfernt.','#/destinations')}${offerCards()}</div></section><section class="section section-light"><div class="container"><div class="promo-banner"><div class="promo-content"><span class="eyebrow">MOLLIAIR CITY</span><h2>Mehr Möglichkeiten.<br>Einfach verbunden.</h2><p>Unsere Regionalverbindungen bringen dich über Mollicity zu neuen Horizonten. Entdecke das Streckennetz der Zukunft.</p>${button('Molliair City entdecken','#/city','lime')}</div><div class="promo-photo" role="img" aria-label="Flugzeug über den Wolken"></div></div></div></section><section class="section"><div class="container">${sectionHeading('Entspannt reisen','Alles für eine gute Reise','Von der Buchung bis zur Ankunft – diese Services helfen dir unterwegs.')}<div class="info-3">${[['bag','Gepäck einfach planen','Finde den passenden Tarif und erfahre, wie viel Gepäck du mitnehmen kannst.','baggage'],['seat','Dein Platz an Bord','Wähle deinen Sitzplatz und ergänze Services vor deiner Reise.','experience'],['heart','Vorteile mit Club','Entdecke Molliair Club und gestalte deine Reisen ganz nach deinen Wünschen.','club']].map(x=>`<div class="info-card"><div class="icon-box">${icon(x[0])}</div><h3>${x[1]}</h3><p>${x[2]}</p><a href="#/${x[3]}">Mehr erfahren →</a></div>`).join('')}</div></div></section><section class="section section-light"><div class="container">${sectionHeading('Netz & Neuigkeiten','Eine neue Ära für Molliair','Mit Aurelia Regional Group entwickeln wir unseren Standort Mollicity und investieren in die Zukunft des Reisens.')}${button('Unsere Geschichte','#/about','dark')} <a class="link small" style="margin-left:20px" href="#/news">Aktuelle Meldungen →</a></div></section>${newsletter()}`}
function newsletter(){return `<div class="newsletter"><div class="container newsletter-inner"><div><span class="eyebrow">MOLLIAIR UPDATES</span><h2>Inspiration direkt ins Postfach</h2><p>Neue Flugziele, Angebote und Geschichten rund um Molliair.</p></div><form id="newsletterForm"><input type="email" required name="email" placeholder="Deine E-Mail-Adresse" aria-label="E-Mail-Adresse"> <button class="btn btn-dark" type="submit">Interesse merken ${icon('arrow')}</button></form></div></div>`}
function renderBooking(){return `<div class="compact-search"><div class="container">${pageHeroInline('Flüge suchen','Plane deine nächste Reise mit Molliair.')}${searchWidget()}</div></div><section class="section"><div class="container">${sectionHeading('Entdecken','Für jede Reise der passende Tarif','Flexibel bleiben, unkompliziert reisen oder mehr Komfort genießen – du hast die Wahl.')}${renderTariffInfo()}</div></section>`}
function pageHeroInline(title,desc){return `<div style="margin:0 0 24px"><div class="bread"><a href="#/home">Startseite</a> › ${E(title)}</div><h1 style="font-size:37px;margin:11px 0 8px">${E(title)}</h1><p class="muted small">${E(desc)}</p></div>`}
function tripSteps(active){let keys=['results','fares','passengers','extras','review'],labels=['Flüge','Tarif','Reisende','Extras','Übersicht'];let i=keys.indexOf(active);return `<div class="stepper">${labels.map((x,j)=>`<div class="step ${j===i?'active':j<i?'done':''}"><b>${j<i?'✓':j+1}</b>${x}</div>`).join('')}</div>`}
function bookingTitle(){const f=STATE.form;return `${codeName(f.from)} → ${codeName(f.to)}${f.trip==='round'?' · Hin & zurück':''}`}
function summaryBox(actions=false){const b=STATE.booking,f=STATE.form;if(!b.out)return `<div class="panel side-sticky"><div class="eyebrow">DEINE REISE</div><h3 style="margin-top:10px">${E(codeName(f.from))} → ${E(codeName(f.to))}</h3><p class="muted small">${C.fmtDate(f.dateOut)}${f.trip==='round'?' – '+C.fmtDate(f.dateIn):''} · ${C.passengersCount(f).heads} Reisende</p><div class="divider"></div><p class="muted small">Wähle einen Flug aus, um deinen Gesamtpreis und alle Reiseleistungen zu sehen.</p></div>`;const p=C.quote([b.out,b.back],f,b.fare,b.extras);return `<div class="panel side-sticky"><div class="eyebrow">DEINE REISE</div><h3 style="margin-top:8px">${E(codeName(f.from))} <span style="color:#8195a2">→</span> ${E(codeName(f.to))}</h3><p class="muted small">${C.fmtDate(f.dateOut)}${f.trip==='round'?` – ${C.fmtDate(f.dateIn)}`:''} · ${C.passengersCount(f).heads} Reisende</p><div class="divider"></div>${b.out?miniItinerary(b.out,'Hinflug'):''}${b.back?miniItinerary(b.back,'Rückflug'):''}<div class="divider"></div><div class="sum-row"><span>Flugpreis</span><strong>${euro(p.base)}</strong></div><div class="sum-row"><span>Tarif ${E(b.fare)}</span><strong>${euro(p.tariff)}</strong></div>${p.bags?`<div class="sum-row"><span>Zusatzgepäck</span><strong>${euro(p.bags)}</strong></div>`:''}${p.seats?`<div class="sum-row"><span>Sitzplatz</span><strong>${euro(p.seats)}</strong></div>`:''}${p.meals?`<div class="sum-row"><span>Menü an Bord</span><strong>${euro(p.meals)}</strong></div>`:''}${p.priority?`<div class="sum-row"><span>Priority</span><strong>${euro(p.priority)}</strong></div>`:''}<div class="sum-total"><b>Gesamtpreis</b><strong class="price">${euro(p.total)}</strong></div><p class="note">Alle Steuern und Gebühren enthalten. Endpreis wird beim Weitergehen aktualisiert.</p>${actions?`<div style="margin-top:18px">${button('Zur Flugauswahl','#/results','outline','btn-full')}</div>`:''}</div>`}
function miniItinerary(r,label){
 const hops=r.viaAirports|| (r.via?[r.via]:[]);
 return `<div style="margin:12px 0"><span class="eyebrow">${label}</span><div class="flex between align-center" style="margin:7px 0"><strong>${r.legs[0].depart} ${r.from}</strong><span class="muted tiny">${r.stops===0?'Direkt':'via '+hops.join(', ')}</span><strong>${r.arrive} ${r.to}</strong></div><div class="tiny muted">${C.fmtDate(r.date)}${r.arriveDate!==r.date?' → '+C.fmtDate(r.arriveDate):''} · ${r.flightNo}</div></div>`;
}
function flightCard(it,phase){
 const via=(it.viaAirports||[]).map(codeName);
 const stops=it.stops===0?'Direktflug':it.stops+' '+(it.stops===1?'Umstieg':'Umstiege')+' via '+via.join(' & ');
 const operators=[...new Set(it.legs.map(l=>operatorName(l.carrier)))].join(' · ');
 const otherOperators=hasOtherOperators(it);
 const warning=it.overnight?'Übernachtung auf der Reise':it.longConnection?'Längerer Zwischenaufenthalt':'';
 const nextDay=it.arriveDate!==it.date?`<span class="result-date-offset">+ ${E(C.fmtDate(it.arriveDate))}</span>`:'';
 const layovers=it.connectionMinutes||[];
 return `<article class="result-card ${warning?'result-long':''}">
  <div class="result-top"><span><span class="status-dot"></span> ${E(operators)} ${otherOperators?'<span class="operator-tag">Weitere Airline</span>':''}</span><span>${it.legs.map(l=>E(l.aircraft)).filter((x,i,a)=>a.indexOf(x)===i).join(' / ')}</span></div>
  <div class="result-body"><div class="flight-times"><div class="time-point"><strong>${it.depart}</strong><span>${it.from}</span></div><div class="flight-line"><small>${C.timeDuration(it.minutes)}</small><div class="rule"></div><div class="stop">${E(stops)}</div></div><div class="time-point"><strong>${it.arrive}</strong><span>${it.to}</span>${nextDay}</div></div>
  <div class="result-price"><div><strong class="price">${euro(it.price)}</strong><small>Richtpreis / Person · ${otherOperators?'Partneroption':'LIGHT'}</small></div><button class="btn btn-lime btn-sm" data-action="choose-flight" data-phase="${phase}" data-id="${E(it.id)}">Auswählen ${icon('arrow')}</button></div></div>
  ${otherOperators?`<div class="partner-disclosure">${icon('info')} Reise mit anderer Fluggesellschaft: gemeinsame Ticketbuchung und Gepäckweiterleitung sind im Planungsnetz nicht bestätigt. Die ausführende Airline wird je Flugabschnitt angezeigt.</div>`:''}
  ${warning?`<div class="connection-warning">${icon('clock')} ${E(warning)} · ${layovers.map((m,i)=>C.timeDuration(m)+' in '+via[i]).join(' · ')}. Bitte Anschluss- und Übernachtungsmöglichkeiten beachten.</div>`:''}
  <details class="flight-details"><summary>Flugdetails und Umsteigezeiten <span>⌄</span></summary><div class="flight-timeline">${it.legs.map((l,i)=>`<div class="flight-segment"><div class="segment-rail"><span class="segment-dot"></span><span class="segment-bar"></span><span class="segment-dot"></span></div><div class="segment-info"><strong>${E(l.depart)} ${E(l.from)} <span>→</span> ${E(l.arrive)} ${E(l.to)}</strong><small>${E(C.fmtDate(l.departDate))}${l.arriveDate!==l.departDate?' → '+E(C.fmtDate(l.arriveDate)):''} · ${E(l.flightNo)} · ${E(l.aircraft)} · ${E(operatorName(l.carrier))} ${!['ML','MC'].includes(l.carrier)?'· Ausgeführt von anderer Airline':''}</small></div></div>${i<layovers.length?`<div class="segment-wait">${icon('clock')} ${C.timeDuration(layovers[i])} Aufenthalt in ${E(codeName(l.to))}${layovers[i]>=360?' · längerer Aufenthalt':''}${l.arriveDate!==it.legs[i+1].departDate?' · über Nacht':''}</div>`:''}`).join('')}</div></details>
  <div class="result-bottom"><span>${E(it.flightNo)} · ${C.fmtDate(it.date)}</span><strong>${it.stops===0?'Ohne Umstieg':E(stops)}</strong></div>
 </article>`;
}
function searchDates(phase){
 const f=STATE.form,base=phase==='out'?f.dateOut:f.dateIn;
 const from=phase==='out'?f.from:f.to,to=phase==='out'?f.to:f.from;
 const cap=STATE.connectionFilter==='direct'?0:STATE.connectionFilter==='one'?1:2;
 return `<div class="date-strip" aria-label="Flugpreise an anderen Tagen">${[-3,-2,-1,0,1,2,3].map(delta=>{
  const d=C.dateShift(base,delta),ok=d>='2026-11-23'&&d<='2027-10-31';
  const options=ok?C.search(D,from,to,d,{maxStops:cap,sort:'price',airlineScope:STATE.airlineScope}):[];
  return `<button class="date-chip ${delta===0?'active':''}" data-action="change-search-date" data-phase="${phase}" data-date="${d}" ${ok?'':'disabled'}><span>${new Intl.DateTimeFormat('de-DE',{weekday:'short',timeZone:'UTC'}).format(C.parseDay(d))}</span><strong>${d?.slice(8)}.${d?.slice(5,7)}.</strong><span>${options.length?'ab '+euro(options[0].price):'–'}</span></button>`;
 }).join('')}</div>`;
}
function renderResults(){
 let f=STATE.form,phase=STATE.resultPhase;
 if(f.trip==='one'&&phase==='return')phase='out';
 const from=phase==='out'?f.from:f.to,to=phase==='out'?f.to:f.from,date=phase==='out'?f.dateOut:f.dateIn;
 const stops=STATE.connectionFilter==='direct'?0:STATE.connectionFilter==='one'?1:2;
 const results=C.search(D,from,to,date,{sort:STATE.sort,maxStops:stops,airlineScope:STATE.airlineScope});
 const alternatives=results.length?[]:C.nextAvailableDates(D,from,to,date,{days:21,maxStops:stops,airlineScope:STATE.airlineScope}).filter(x=>x.date<='2027-10-31');
 return pageHero('Flug auswählen',`${E(bookingTitle())} · ${E(C.fmtDate(date,true))}`)+`<div class="page-main"><div class="container">${tripSteps('results')}<div class="grid-sidebar"><div>
 <div class="flex between align-center" style="flex-wrap:wrap;gap:12px"><h2 style="font-size:25px">${phase==='out'?'Dein Hinflug':'Dein Rückflug'}</h2><a href="#/booking" class="link small">Suche ändern</a></div>
 <div class="connection-info">${icon('plane')} Direktflüge und Umsteigeverbindungen von Molliair und weiteren Fluggesellschaften. Jede ausführende Airline wird ausgewiesen.</div>
 ${searchDates(phase)}
 <div class="result-toolbar"><span class="muted small">${results.length} ${results.length===1?'Verbindung':'Verbindungen'} am ${E(C.fmtDate(date))}</span>
 <div class="result-controls"><label class="small">Fluggesellschaft <select id="airlineScope" aria-label="Fluggesellschaften filtern"><option value="all" ${STATE.airlineScope==='all'?'selected':''}>Molliair + weitere Airlines</option><option value="arg" ${STATE.airlineScope==='arg'?'selected':''}>Nur Molliair-Gruppe</option><option value="partner" ${STATE.airlineScope==='partner'?'selected':''}>Mit anderen Airlines</option></select></label><label class="small">Umsteigen <select id="filterConnections"><option value="all" ${STATE.connectionFilter==='all'?'selected':''}>Alle Verbindungen</option><option value="direct" ${STATE.connectionFilter==='direct'?'selected':''}>Nur Direktflüge</option><option value="one" ${STATE.connectionFilter==='one'?'selected':''}>Max. 1 Umstieg</option></select></label>
 <label class="small">Sortieren <select id="sortFlights"><option value="recommended" ${STATE.sort==='recommended'?'selected':''}>Empfohlen</option><option value="price" ${STATE.sort==='price'?'selected':''}>Günstigster Preis</option><option value="duration" ${STATE.sort==='duration'?'selected':''}>Kürzeste Reisezeit</option><option value="time" ${STATE.sort==='time'?'selected':''}>Frühester Abflug</option></select></label></div></div>
 <div class="partner-results-note">${icon('info')} Flüge anderer Airlines sind als Planungsoption sichtbar. Es liegt keine bestätigte gemeinsame Ticket- oder Gepäckabwicklung zugrunde; Preise sind Beispiele.</div>
 ${results.length?results.map(it=>flightCard(it,phase)).join(''):`<div class="empty"><div style="font-size:35px;margin-bottom:8px">✈</div><h3>Keine passende Verbindung für diesen Reisetag</h3><p style="margin:10px 0 20px">Prüfe einen anderen Tag oder erlaube Umstiege. Es werden keine Flüge ohne passende Flugzeiten erfunden.</p>${alternatives.length?`<div class="alternative-dates"><strong>Nächste mögliche Reisetage</strong><div class="alternative-grid">${alternatives.map(x=>`<button class="alternative-option" data-action="change-search-date" data-phase="${phase}" data-date="${x.date}"><span>${E(C.fmtDate(x.date))}</span><b>ab ${euro(x.itinerary.price)}</b><small>${x.itinerary.stops===0?'Direkt':x.itinerary.stops+' Umstieg(e)'}</small></button>`).join('')}</div></div>`:''}${button('Neue Suche starten','#/booking','outline')}</div>`}
 </div><aside>${summaryBox(true)}<div class="alert" style="margin-top:14px">${icon('info')} Tarifpreise sind unverbindliche Berechnungen innerhalb der Reiseplanung. Keine Live-Verfügbarkeit oder Ticketbuchung.</div></aside></div></div></div>`;
}
function renderTariffInfo(){return `<div class="tariff-grid">${Object.entries(C.FARES).map(([id,f])=>`<div class="tariff-card" style="cursor:default"><h4>${id}</h4><strong class="price">${id==='LIGHT'?'Inklusive':'+'+euro(f.extra)}</strong><p>${f.cabin} kg Handgepäck<br>${f.checked?f.checked+' kg Aufgabegepäck':'Aufgabegepäck zubuchbar'}<br>Umbuchung: ${f.change}</p><span class="tag">${id==='BUSINESS'?'Mehr Komfort':'Economy'}</span></div>`).join('')}</div>`}
function renderFares(){const b=STATE.booking;if(!b.out)return renderResults();const q=C.quote([b.out,b.back],STATE.form,b.fare,b.extras);return pageHero('Deinen Tarif wählen','Bestimme selbst, wie flexibel und komfortabel du reisen möchtest.')+`<div class="page-main"><div class="container">${tripSteps('fares')}<div class="grid-sidebar"><div><div class="panel"><span class="eyebrow">MEHR KOMFORT, MEHR FREIHEIT</span><h2 style="font-size:26px;margin-top:8px">Welcher Tarif passt zu dir?</h2><div class="tariff-grid">${Object.entries(C.FARES).filter(([k])=>(!bookingHasOtherOperators()||['CLASSIC','BUSINESS'].includes(k))&&(k!=='BUSINESS'||[b.out,b.back].filter(Boolean).every(x=>x.business))).map(([id,f])=>`<button data-action="choose-fare" data-fare="${id}" class="tariff-card ${id===b.fare?'active':''}"><h4>${id}</h4><strong class="price">${f.extra?`+ ${euro(f.extra)}`:'Inklusive'}</strong><p>Handgepäck: ${f.cabin} kg<br>${f.checked?f.checked+' kg Aufgabegepäck':'Aufgabegepäck optional'}<br>Umbuchen: ${f.change}<br>${f.seat?'Sitzplatz inklusive':'Sitzplatz optional'}</p><span class="tag">${id===b.fare?'✓ Ausgewählt':'Tarif wählen'}</span></button>`).join('')}</div><div class="alert">Tarifzuschläge gelten je Flugabschnitt und Reisendem. Bei einer Umsteigeverbindung wird der Tarif für beide Abschnitte berücksichtigt.</div></div><div class="flex between" style="margin-top:21px;gap:12px">${button('← Zurück','#/results','outline')}<button class="btn btn-lime" data-action="continue-fare">Weiter zu den Reisenden ${icon('arrow')}</button></div></div><aside>${summaryBox()}</aside></div></div></div>`}
function passengersFields(){const p=C.passengersCount(STATE.form),list=[];for(let i=0;i<p.adults;i++)list.push({type:'Erwachsene/r',index:i});for(let i=0;i<p.children;i++)list.push({type:'Kind',index:p.adults+i});return list.map((person)=>{const v=STATE.booking.people[person.index]||{};return `<div class="panel traveler-section"><h3>Reisende/r ${person.index+1} <span class="pill">${person.type}</span></h3><div class="form-grid"><div class="form-field"><label for="first${person.index}">Vorname *</label><input id="first${person.index}" name="first${person.index}" value="${E(v.first||'')}" maxlength="55" required autocomplete="given-name" placeholder="Wie im Ausweis"></div><div class="form-field"><label for="last${person.index}">Nachname *</label><input id="last${person.index}" name="last${person.index}" value="${E(v.last||'')}" maxlength="55" required autocomplete="family-name" placeholder="Wie im Ausweis"></div><div class="form-field"><label for="gender${person.index}">Anrede</label><select id="gender${person.index}" name="gender${person.index}"><option value="">Bitte auswählen</option><option value="Frau" ${v.gender==='Frau'?'selected':''}>Frau</option><option value="Herr" ${v.gender==='Herr'?'selected':''}>Herr</option><option value="Divers" ${v.gender==='Divers'?'selected':''}>Divers</option></select></div><div class="form-field"><label for="birth${person.index}">Geburtsdatum *</label><input id="birth${person.index}" type="date" name="birth${person.index}" value="${E(v.birth||'')}" min="1900-01-01" max="2026-11-23" required></div></div></div>`}).join('')}
function renderPassengers(){if(!STATE.booking.out)return renderResults();const b=STATE.booking;return pageHero('Deine Reisedaten','Gib die Namen aller Reisenden so ein, wie sie im Ausweisdokument stehen.')+`<div class="page-main"><div class="container">${tripSteps('passengers')}<form id="passengerForm"><div class="grid-sidebar"><div>${passengersFields()}<div class="panel"><h3>Kontaktinformationen</h3><div class="form-grid" style="margin-top:18px"><div class="form-field"><label>E-Mail-Adresse *</label><input type="email" name="email" required placeholder="name@beispiel.de" value="${E(b.email)}" autocomplete="email"></div><div class="form-field"><label>Mobiltelefon</label><input type="tel" name="phone" placeholder="+49 170 ..." value="${E(b.phone)}" autocomplete="tel"></div></div><p class="note" style="margin-top:14px">Deine Angaben werden nur für den lokalen Reiseplan dieser Website verwendet.</p></div><div class="flex between" style="margin-top:19px;gap:12px">${button('← Tarif ändern','#/fares','outline')}<button class="btn btn-lime" type="submit">Weiter zu Extras ${icon('arrow')}</button></div></div><aside>${summaryBox()}</aside></div></form></div></div>`}
function seats(){if(bookingHasOtherOperators())return `<div class="panel"><h3>Sitzplatzwahl bei Partnerflügen</h3><p class="muted small">Sitzplätze auf Flügen anderer Airlines können in dieser Reiseplanung nicht reserviert werden. Bitte prüfe die Möglichkeiten bei der ausführenden Fluggesellschaft.</p></div>`;const chosen=STATE.booking.selectedSeats;const aircraft=STATE.booking.out?.legs?.[0]?.aircraft||'E190-E2';const limit=aircraft.includes('E195')?33:27;let rows=[];for(let r=1;r<=limit;r++){let seatRow=`<div class="seat-row"><span class="seat-label">${r}</span>`;for(let i=0;i<4;i++){if(i===2)seatRow+='<span class="aisle"></span>';let seat=r+['A','B','C','D'][i],blocked=(r*13+i*7)%11===0||(aircraft.includes('E190')&&r===27&&i>=2);seatRow+=`<button type="button" class="seat ${chosen.includes(seat)?'selected':blocked?'occupied':''}" data-action="seat" data-seat="${seat}" ${blocked?'disabled':''} aria-label="Sitz ${seat}" aria-pressed="${chosen.includes(seat)}">${['A','B','C','D'][i]}</button>`}rows.push(seatRow+'</div>')};return `<div class="seat-panel"><div class="flex between align-center"><div><h3>Sitzplatz auswählen</h3><p class="muted small">2–2 Bestuhlung · ${E(aircraft)} · ${aircraft.includes('E195')?132:106} Sitze</p></div><span class="pill">${STATE.booking.selectedSeats.length} gewählt</span></div><div class="seat-map"><div class="text-center tiny muted" style="margin-bottom:18px">FLUGZEUGSPITZE ↑</div>${rows.join('')}</div><div class="seat-legend"><span><i style="background:#fff"></i> Frei</span><span><i style="background:#c9e93a;border-color:#7eaf27"></i> Ausgewählt</span><span><i style="background:#cbd9df"></i> Belegt</span></div><p class="note text-center" style="margin-top:12px">Sitzplatzauswahl für den ersten Flugabschnitt. Die Darstellung ist eine Vorschau; Sitzplätze werden nicht bei einer Airline reserviert.</p></div>`}
function renderExtras(){if(!STATE.booking.out)return renderResults();const b=STATE.booking,e=b.extras,ins=C.FARES[b.fare];return pageHero('Mach die Reise zu deiner Reise','Wähle zusätzliche Services für mehr Komfort unterwegs.')+`<div class="page-main"><div class="container">${tripSteps('extras')}<div class="grid-sidebar"><div><div class="panel"><span class="eyebrow">DEINE EXTRAS</span><h2 style="font-size:26px;margin-top:8px;margin-bottom:19px">So reist du noch entspannter</h2><div class="extras-grid">${bookingHasOtherOperators()?'':`<label class="extra-card"><input type="checkbox" data-action="extra-check" data-extra="bags" ${e.bags?'checked':''}><div><h4>Zusätzliches Aufgabegepäck</h4><p>Ein weiterer Koffer mit bis zu 23 kg pro Strecke, zusätzlich zum Tarif.</p></div><b class="price">+29 €</b></label><label class="extra-card"><input type="checkbox" data-action="extra-check" data-extra="meals" ${e.meals?'checked':''}><div><h4>Menü an Bord</h4><p>Ein warmes Menü für deinen nächsten Flug.</p></div><b class="price">+13 €</b></label><label class="extra-card"><input type="checkbox" data-action="extra-check" data-extra="priority" ${e.priority?'checked':''}><div><h4>Priority Boarding</h4><p>Früher einsteigen und entspannt Platz nehmen.</p></div><b class="price">+19 €</b></label><a href="#/baggage" class="extra-card"><span style="font-size:23px">ⓘ</span><div><h4>Dein Tarif ${b.fare}</h4><p>Inklusive: ${ins.cabin} kg Handgepäck, ${ins.checked?ins.checked+' kg Aufgabegepäck':'Gepäck optional'}.</p><span class="link tiny">Tarifdetails öffnen →</span></div></a>`}</div></div>${seats()}${bookingHasOtherOperators()?`<div class="alert" style="margin-top:15px">Für Flüge anderer Airlines können Sitzplätze, Mahlzeiten, Priority Boarding und Zusatzgepäck andere Regeln und Preise haben. Diese Leistungen werden nicht verbindlich zugesagt.</div>`:''}<div class="flex between" style="margin-top:20px;gap:13px">${button('← Zurück','#/passengers','outline')}<button class="btn btn-lime" data-action="continue-extras">Weiter zur Übersicht ${icon('arrow')}</button></div></div><aside>${summaryBox()}</aside></div></div></div>`}
function renderReview(){const b=STATE.booking,f=STATE.form;if(!b.out||!b.people.length)return renderPassengers();const q=C.quote([b.out,b.back],f,b.fare,b.extras);return pageHero('Fast geschafft','Prüfe alle Angaben, bevor du deinen Reiseplan speicherst.')+`<div class="page-main"><div class="container">${tripSteps('review')}<div class="grid-sidebar"><div><div class="panel"><span class="eyebrow">REISEDETAILS</span><h2 style="font-size:25px;margin:9px 0 20px">${E(bookingTitle())}</h2>${miniItinerary(b.out,'Hinflug')}${b.back?`<div class="line" style="margin:19px 0"></div>${miniItinerary(b.back,'Rückflug')}`:''}<div class="divider"></div><h3>Reisende</h3>${b.people.map((p,i)=>`<div class="sum-row"><span>Person ${i+1}</span><strong>${E(p.first+' '+p.last)}</strong></div>`).join('')}<div class="sum-row"><span>E-Mail</span><strong>${E(b.email)}</strong></div><div class="divider"></div><h3>Tarif und Extras</h3><div class="sum-row"><span>Tarif</span><strong>${E(b.fare)}</strong></div>${b.selectedSeats.length?`<div class="sum-row"><span>Sitzplätze</span><strong>${E(b.selectedSeats.join(', '))}</strong></div>`:''}<div class="sum-row"><span>Zusatzgepäck</span><strong>${b.extras.bags?'Ja':'Nein'}</strong></div></div><div class="alert warn" style="margin-top:15px"><strong>Hinweis zum Buchungsabschluss:</strong> Dies ist eine interaktive Buchungsvorschau. Der Vorgang speichert deinen Reiseplan ausschließlich in diesem Browser. Es erfolgt keine Zahlung und es wird kein echtes Flugticket ausgestellt.</div><label class="checkbox-line"><input id="bookingAgree" type="checkbox" ${b.agree?'checked':''}><span>Ich habe verstanden, dass ich hier einen Reiseplan speichere und keine zahlungspflichtige Flugbuchung abschließe.</span></label><div class="flex between" style="margin-top:24px;gap:12px">${button('← Extras anpassen','#/extras','outline')}<button class="btn btn-lime btn-lg" data-action="confirm-booking" ${b.agree?'':'disabled'}>Reiseplan speichern ${icon('check')}</button></div></div><aside>${summaryBox()}<p class="notice-bottom">Preisübersicht: ${euro(q.total)} für ${C.passengersCount(f).heads} Reisende.</p></aside></div></div></div>`}
function bookingRecord(){const f=STATE.form,b=STATE.booking,price=C.quote([b.out,b.back],f,b.fare,b.extras);const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const code='ML'+Array.from({length:5},()=>chars[Math.floor(Math.random()*chars.length)]).join('');return {code,created:new Date().toISOString(),form:{...f},out:b.out,back:b.back,fare:b.fare,people:b.people,email:b.email,phone:b.phone,extras:{...b.extras},selectedSeats:[...b.selectedSeats],total:price.total,checkedIn:false,cancelled:false}}
function renderSuccess(){const found=STATE.managed;return pageHero('Reiseplan gespeichert','Alle Informationen findest du in deiner persönlichen Reiseübersicht.')+`<div class="page-main"><div class="container" style="max-width:760px"><div class="confirm-card"><div class="success-mark">✓</div><span class="eyebrow">ALLES AN EINEM ORT</span><h2>Deine Reise ist vorgemerkt.</h2><p class="muted" style="margin-top:9px">Mit dem folgenden Code kannst du deinen gespeicherten Reiseplan jederzeit in diesem Browser aufrufen.</p><div class="booking-code">${E(found?.code||'')}</div><p class="small"><strong>${E(codeName(found?.form?.from||'MOL'))} → ${E(codeName(found?.form?.to||'MIA'))}</strong> · ${E(C.fmtDate(found?.form?.dateOut))}</p><div class="alert" style="margin:21px 0">Es wurde kein Ticket verkauft oder ausgestellt. Dein Reiseplan ist lokal gespeichert und kann über „Meine Buchung“ geöffnet werden.</div><div class="flex" style="flex-wrap:wrap;gap:11px;margin-top:21px">${button('Reiseplan öffnen','#/manage','dark')}<button class="btn btn-outline" data-action="print">Drucken</button>${button('Zur Startseite','#/home','soft')}</div></div></div></div>`}
function renderDestinations(){const active=STATE.destinationRegion;const d=OFFERS.concat([{code:'MHH',from:49,class:'dest-mbg',tag:'Molliland entdecken',sub:'Molliland'}]);const list=d.filter(x=>active==='all'||(active==='regional'&&['MBG','MHH','MST','STC'].includes(x.code))||(active==='international'&&!['MBG','MHH','MST','STC'].includes(x.code))||(active==='future'&&['GEO','PTY'].includes(x.code)));return pageHero('Unsere Reiseziele','Entdecke vertraute Lieblingsorte und neue Perspektiven – direkt ab Mollicity oder mit einer komfortablen Verbindung.')+`<section class="page-main"><div class="container">${sectionHeading('REISEZIELE','Finde deinen nächsten Lieblingsort','Reiseziele mit Molliair und Molliair City.') }<div class="filter-row">${[['all','Alle Ziele'],['regional','Regional & Nachbarländer'],['international','International'],['future','Neue Ziele']].map(x=>`<button data-action="destination-filter" data-filter="${x[0]}" class="btn ${active===x[0]?'btn-dark':'btn-soft'} btn-sm">${x[1]}</button>`).join('')}</div>${offerCards(list)}<div class="alert" style="margin-top:26px">Für Ziele mit Start ab 2030 werden derzeit Ausbaupläne angezeigt. Buchungsdaten sind erst nach Veröffentlichung des jeweiligen Flugplans verfügbar.</div></div></section>`}
function renderOffers(){return pageHero('Flugangebote','Es gibt immer einen guten Grund, loszufliegen. Entdecke unsere Strecken ab Mollicity.')+`<section class="page-main"><div class="container">${sectionHeading('Flüge ab Mollicity','Besondere Reiseziele. Attraktive Einstiegspreise.','Preise pro Person und Flugrichtung im Tarif LIGHT. Der tatsächlich angezeigte Preis hängt vom Reisedatum und den verfügbaren Verbindungen ab.')}<div class="list-grid">${OFFERS.filter(x=>!['GEO','PTY'].includes(x.code)).map(x=>`<div class="route-card"><div><span class="eyebrow">MOL → ${x.code}</span><div class="route-city">${E(codeName(x.code))}</div><div class="route-country">${E(country(x.code))}</div><span class="pill good" style="margin-top:12px">ab ${euro(x.from)}</span></div><button class="btn btn-lime btn-sm" data-action="offer-search" data-dest="${x.code}">Flüge suchen ${icon('arrow')}</button></div>`).join('')}</div><div class="alert" style="margin-top:28px">Alle Preisangaben sind Beispieltarife zur Reiseplanung. Im nächsten Schritt werden konkrete Verbindungen für dein Reisedatum angezeigt.</div></div></section>`}
function renderDestination(code){const x=OFFERS.find(x=>x.code===code)||{code,from:49,class:'dest-mbg',tag:'Reiseziel',sub:country(code)};const airport=D.airports.find(a=>a.code===code);if(!airport)return renderDestinations();const route=D.routes.find(r=>r.carrier==='ML'&&r.from==='MOL'&&r.to===code),freq=route?.byYear[2027]||0;let desc={MIA:'Sonne, pulsierende Stadt und weite Strände. Entdecke Miami als Ausgangspunkt für unvergessliche Erlebnisse.',STC:'Von Mollicity schnell in die lebendige Hauptstadt Stachellands. Ideal für Business, Kultur und einen Kurztrip.',MST:'Eine kleine Inselstadt mit großer Ausstrahlung. Die Verbindung nach Mialand ergänzt unser Sommernetz.',BEL:'Brasiliens Norden entdecken: Kultur, Geschichte und Natur am Tor zum Amazonas.',TNR:'Lerne faszinierende Landschaften und die Vielfalt Madagaskars kennen.',MBG:'Molliburg entdecken und unkompliziert mit der Hauptstadt verbunden bleiben.',MHH:'Ein kurzer Weg nach Mollicity und komfortable Weiterreisen ins internationale Netz.',GEO:'Guyana steht auf unserer langfristigen internationalen Ausbauagenda.',PTY:'Panama-Stadt ergänzt die geplante Erweiterung des internationalen Netzes.'}[code]||'Entdecke eine weitere Destination im Molliair Streckennetz.';return `<section class="page-hero dark"><div class="container"><div class="bread"><a href="#/destinations">Reiseziele</a> › ${E(airport.name)}</div><div class="detail-title" style="margin:20px 0 12px"><h1>${E(airport.name)}</h1><span class="iata">${code}</span></div><p>${E(desc)}</p><div class="flex align-center gap16" style="margin-top:24px;flex-wrap:wrap"><span class="pill">${E(airport.country)}</span><span class="pill">${freq?freq+'× wöchentlich':'Geplanter Ausbau'}</span><span class="pill">Hinflug ab ${euro(x.from)}</span></div></div></section><div class="page-main"><div class="container grid-sidebar"><div><div class="panel"><span class="eyebrow">REISEDETAILS</span><h2 style="margin:10px 0 18px;font-size:28px">Flüge nach ${E(airport.name)}</h2><p class="muted">${E(desc)}</p><div class="divider"></div><div class="feature-list"><div class="feature-item"><span>✈</span><div><h4>Verbindung</h4><p>${freq?'Direkt ab Mollicity':'In Vorbereitung'}</p></div></div><div class="feature-item"><span>◷</span><div><h4>Flugtage</h4><p>${route?E(route.days.join(' · ')):'Wird bekanntgegeben'}</p></div></div><div class="feature-item"><span>▣</span><div><h4>Flugzeug</h4><p>${route?E(route.aircraft):'Embraer E190-E2 geplant'}</p></div></div><div class="feature-item"><span>◇</span><div><h4>Abflugort</h4><p>Mollicity International (MOL)</p></div></div></div></div><div class="panel" style="margin-top:18px"><h3>Dein nächster Schritt</h3><p class="muted small">Wähle dein Datum und finde alle passenden Verbindungen über unser Streckennetz.</p><div style="margin-top:18px">${button('Alle Reiseziele ansehen','#/destinations','outline')}</div></div></div><aside><div class="panel side-sticky"><span class="eyebrow">ANGEBOT</span><h3 style="margin:9px 0">Deine Reise nach ${E(airport.name)}</h3><div class="price" style="font-size:35px;margin:14px 0">ab ${euro(x.from)}</div><p class="muted small">pro Person und Strecke im LIGHT-Tarif</p><div style="margin-top:22px"><button class="btn btn-lime btn-full" data-action="offer-search" data-dest="${code}" ${freq?'':'disabled'}>Flüge suchen ${icon('arrow')}</button></div>${!freq?'<p class="note" style="margin-top:12px">Der Flugplan für dieses Ziel ist noch nicht zur Suche freigegeben.</p>':''}</div></aside></div></div>`}
function findReservation(form){const code=String(form.get('pnr')||'').trim().toUpperCase(),last=String(form.get('last')||'').trim().toLocaleLowerCase('de');return bookings().find(b=>b.code===code&&b.people?.some(p=>p.last.toLocaleLowerCase('de')===last))||null}
function lookupForm(which){return `<form id="lookupForm" data-kind="${which}" class="panel" style="max-width:640px"><h3 style="margin-bottom:18px">${which==='manage'?'Deine Reise aufrufen':'Online Check-in'}</h3><div class="form-grid"><div class="form-field"><label for="pnrLookup">Buchungscode *</label><input id="pnrLookup" name="pnr" required placeholder="z. B. ML4X7K" maxlength="12"></div><div class="form-field"><label for="lastLookup">Nachname *</label><input id="lastLookup" name="last" required placeholder="Nachname auf dem Reiseplan"></div></div><button class="btn btn-lime" type="submit" style="margin-top:21px">${which==='manage'?'Buchung suchen':'Check-in starten'} ${icon('arrow')}</button><p class="note" style="margin-top:16px">Gespeicherte Reisepläne stehen nur in dem Browser zur Verfügung, in dem sie erstellt wurden.</p></form>`}
function renderManage(){const b=STATE.managed;return pageHero('Meine Buchung','Alle Details zu deiner Reise: Reisedaten, Reisende und zusätzliche Services.')+`<div class="page-main"><div class="container">${b?`<div class="grid-sidebar"><div><div class="panel"><div class="flex between align-center" style="gap:14px;flex-wrap:wrap"><div><span class="eyebrow">BUCHUNGSCODE</span><h2 style="margin:9px 0;font-size:30px;letter-spacing:.12em">${E(b.code)}</h2></div><span class="pill ${b.cancelled?'yellow':'good'}">${b.cancelled?'Reiseplan storniert':'Reiseplan gespeichert'}</span></div><div class="divider"></div>${miniItinerary(b.out,'Hinflug')}${b.back?miniItinerary(b.back,'Rückflug'):''}<div class="divider"></div><h3>Reisende</h3>${b.people.map(p=>`<div class="sum-row"><span>${E(p.first+' '+p.last)}</span><strong>${E(p.birth)}</strong></div>`).join('')}<div class="divider"></div><h3>Deine Services</h3><div class="sum-row"><span>Tarif</span><strong>${E(b.fare)}</strong></div><div class="sum-row"><span>Sitzplätze</span><strong>${E(b.selectedSeats.join(', ')||'Noch keine Auswahl')}</strong></div><div class="sum-row"><span>Zusatzgepäck</span><strong>${b.extras.bags?'Ja':'Nein'}</strong></div></div><div class="panel" style="margin-top:18px"><h3>Weitere Möglichkeiten</h3><p class="muted small" style="margin:9px 0 18px">Du kannst deinen gespeicherten Reiseplan lokal ändern oder löschen.</p><div class="flex" style="gap:10px;flex-wrap:wrap"><button data-action="print" class="btn btn-outline btn-sm">Drucken</button>${!b.cancelled?`<button data-action="manage-bag" class="btn btn-soft btn-sm">Zusatzgepäck ändern</button><button data-action="manage-cancel" class="btn btn-outline btn-sm">Reiseplan stornieren</button>`:''}</div></div></div><aside><div class="panel"><span class="eyebrow">PREISÜBERSICHT</span><h2 class="price" style="margin:12px 0">${euro(b.total)}</h2><p class="note">Gesamtwert des gespeicherten Reiseplans. Es wurde keine Zahlung verarbeitet.</p><div style="margin-top:18px">${button('Online Check-in','#/checkin','dark','btn-full')}</div></div><div class="alert" style="margin-top:13px">Dieser Code ist nur innerhalb dieser Website verwendbar und kein Ticket- oder Airline-Reservierungscode.</div></aside></div>`:lookupForm('manage')}<div style="margin-top:21px">${button('Neue Reise planen','#/booking','soft')}</div></div></div>`}
function renderCheckin(){const b=STATE.checkinBooking;let can=false;if(b){let t=C.parseDay(b.form.dateOut)?.getTime();let now=Date.now();can=t&&now>=t-24*3600*1000&&now<t+4*3600*1000&&!b.cancelled}return pageHero('Online Check-in','Bequem vorbereiten, entspannt ankommen.')+`<div class="page-main"><div class="container">${b?`<div class="grid-sidebar"><div><div class="panel"><span class="eyebrow">DEINE REISE</span><h3 style="margin:9px 0">${E(routeLabel(b.form.from))} → ${E(routeLabel(b.form.to))}</h3><p class="muted small">${E(C.fmtDate(b.form.dateOut,true))} · ${E(b.out.flightNo)}</p><div class="divider"></div><div class="sum-row"><span>Check-in-Status</span><strong>${b.checkedIn?'Vorgemerkt':can?'Verfügbar':'Noch nicht geöffnet'}</strong></div><div class="sum-row"><span>Reisende</span><strong>${b.people.map(p=>E(p.first+' '+p.last)).join(', ')}</strong></div><div class="sum-row"><span>Abflug</span><strong>${b.out.depart}</strong></div><div class="alert" style="margin:19px 0">${b.checkedIn?'Dein Check-in-Vermerk wurde lokal gespeichert.':can?'Die Check-in-Vorschau kann jetzt gestartet werden.':'Der Online Check-in ist ab 24 Stunden vor dem Abflug verfügbar.'} Diese Website stellt keine gültigen Bordkarten aus.</div>${can&&!b.checkedIn?`<button class="btn btn-lime" data-action="checkin-confirm">Check-in-Vermerk speichern</button>`:''}${b.checkedIn?`<button class="btn btn-dark" data-action="print">Reisebestätigung drucken</button>`:''}</div></div><aside><div class="panel"><h3>Wichtige Hinweise</h3><p class="muted small">Halte Ausweis und Reiseunterlagen bereit. Die Check-in-Zeit kann je nach Flughafen unterschiedlich sein.</p></div></aside></div>`:lookupForm('checkin')}</div></div>`}
function renderStatus(){let date=STATE.statusDate||STATE.form.dateOut,flight=STATE.statusFlight||'';let all=C.dateFlights(D,date);let found=flight?all.filter(f=>f.flightNo.replace(/\s/g,'').toUpperCase()===flight.trim().toUpperCase()):all.filter(f=>f.from==='MOL').slice(0,10);return pageHero('Flugstatus & Flugplan','Prüfe geplante Abflüge und Ankünfte unserer Linienverbindungen.')+`<div class="page-main"><div class="container"><form id="statusForm" class="panel"><div class="form-grid"><div class="form-field"><label>Flugnummer (optional)</label><input name="flightno" value="${E(flight)}" placeholder="z. B. ML13501"></div><div class="form-field"><label>Flugdatum</label><input type="date" name="date" value="${E(date)}" min="2026-11-23" max="2027-10-31"></div></div><div style="margin-top:17px"><button class="btn btn-lime" type="submit">Flug suchen ${icon('arrow')}</button></div></form><div class="panel" style="margin-top:24px"><div class="flex between align-center" style="gap:12px;flex-wrap:wrap;margin-bottom:16px"><div><h3>Flüge am ${E(C.fmtDate(date))}</h3><p class="muted small">${found.length} ${found.length===1?'Eintrag':'Einträge'}</p></div><span class="pill yellow">Geplante Zeiten</span></div>${found.length?`<div style="overflow:auto"><table class="mini-table"><thead><tr><th>Flug</th><th>Von</th><th>Nach</th><th>Abflug</th><th>Ankunft</th><th>Status</th></tr></thead><tbody>${found.map(f=>`<tr><td><strong>${E(f.flightNo)}</strong></td><td>${E(f.from)}</td><td>${E(f.to)}</td><td>${E(f.depart)}</td><td>${E(f.arrive)}</td><td><span class="pill yellow">Planzeit</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Für diese Flugnummer und dieses Datum wurde kein Flug im Flugplan gefunden.</div>`}</div><p class="note" style="margin-top:17px">Diese Übersicht zeigt Planzeiten, keine Live-Positionsdaten, Verspätungsinformationen oder Flughafenmeldungen.</p></div></div>`}
function renderBaggage(){return pageHero('Gepäck & Tarife','Alle wichtigen Informationen für deine Reise im Überblick.')+`<div class="page-main"><div class="container">${sectionHeading('AUF EINEN BLICK','Dein Gepäck, dein Tarif','Wähle die passende Reiseklasse und füge bei Bedarf weitere Leistungen hinzu.')}<div class="panel" style="overflow:auto"><table class="mini-table"><thead><tr><th>Leistung</th><th>LIGHT</th><th>CLASSIC</th><th>FLEX</th><th>BUSINESS</th></tr></thead><tbody><tr><td>Handgepäck</td><td>8 kg</td><td>8 kg</td><td>12 kg</td><td>12 kg</td></tr><tr><td>Aufgabegepäck</td><td>Optional</td><td>23 kg</td><td>23 kg</td><td>32 kg</td></tr><tr><td>Sitzplatz</td><td>Optional</td><td>Optional</td><td>Inklusive</td><td>Inklusive</td></tr><tr><td>Umbuchung</td><td>Gebühr</td><td>Gebühr</td><td>Ohne Gebühr</td><td>Ohne Gebühr</td></tr></tbody></table></div><div class="info-3" style="margin-top:21px"><div class="info-card"><div class="icon-box">${icon('bag')}</div><h3>Handgepäck</h3><p>Leichte Taschen und Kabinengepäck bequem mitnehmen. Achte auf die zulässigen Maße und Gewichte.</p></div><div class="info-card"><div class="icon-box">${icon('ticket')}</div><h3>Zusatzgepäck</h3><p>Zusätzliche Gepäckstücke kannst du während der Reiseplanung hinzufügen. Der Preis wird in der Übersicht angezeigt.</p></div><div class="info-card"><div class="icon-box">${icon('info')}</div><h3>Besondere Gegenstände</h3><p>Sportausrüstung, Instrumente und Sondergepäck benötigen eine gesonderte Anfrage.</p></div></div><div class="alert" style="margin-top:25px">Tarifdetails sind für die Flugauswahl dieser Website hinterlegt. Die endgültigen Beförderungsbedingungen werden erst mit einem regulären Buchungssystem verbindlich.</div><div style="margin-top:22px">${button('Jetzt Flüge suchen','#/booking','lime')}</div></div></div>`}
function renderExperience(){return pageHero('An Bord bei Molliair','Deine Zeit über den Wolken – angenehm, unkompliziert und ganz nach deinem Geschmack.',true)+`<section class="page-main"><div class="container"><div class="promo-banner"><div class="promo-content"><span class="eyebrow">WILLKOMMEN AN BORD</span><h2>Ein guter Flug beginnt mit den Details.</h2><p>Moderne Embraer-Flugzeuge mit angenehmer 2–2 Bestuhlung, freundlichem Service und durchdachten Tarifen.</p>${button('Unsere Flotte ansehen','#/fleet','lime')}</div><div class="promo-photo"></div></div><div style="margin-top:43px" class="info-3"><div class="info-card"><div class="icon-box">${icon('seat')}</div><h3>2–2 Sitzanordnung</h3><p>In unseren E190-E2 und E195-E2 gibt es keinen ungeliebten Mittelsitz.</p></div><div class="info-card"><div class="icon-box">${icon('bag')}</div><h3>Tarife für jeden Anlass</h3><p>Wähle LIGHT, CLASSIC, FLEX oder verfügbare Business-Angebote.</p></div><div class="info-card"><div class="icon-box">${icon('heart')}</div><h3>Zusätzlicher Komfort</h3><p>Extras wie ausgewählte Sitzplätze, Zusatzgepäck und Mahlzeiten gehören zur Reiseplanung.</p></div></div></div></section>`}
function renderFleet(){return pageHero('Unsere Flotte','Die moderne Embraer E2-Familie bildet das Herzstück unseres Streckennetzes.')+`<section class="page-main"><div class="container"><div class="fleet-grid">${[['E190-E2','106','Regionalverkehr & internationale Kurzstrecken','Die E190-E2 fliegt für Molliair und bildet langfristig das Rückgrat von Molliair City.','3 Flugzeuge im Plan 2030'],['E195-E2','132','Internationale Hauptstrecken','Die E195-E2 ergänzt die Flotte mit mehr Sitzplätzen und bedient stark nachgefragte Verbindungen.','4 Flugzeuge im Plan 2030']].map(x=>`<div class="card"><div class="fleet-illustration"><span class="plane">✈</span></div><div class="fleet-card-content"><span class="eyebrow">EMBRAER E-JET E2</span><h2 style="margin:8px 0 11px">${x[0]}</h2><p class="muted small">${x[3]}</p><div class="fleet-specs"><span>${x[1]} Sitze</span><span>2–2 Sitzanordnung</span><span>${x[4]}</span></div><p class="bold small">${x[2]}</p></div></div>`).join('')}</div><div class="dark-feature" style="margin-top:30px"><h2>Sieben Flugzeuge. Ein gemeinsames Netzwerk.</h2><p>ARG plant, Molliair und Molliair City bis 2030 schrittweise auf sieben Embraer E2 auszubauen. Die Flottenplanung sieht fünf Flugzeuge für Molliair und zwei für Molliair City vor.</p></div></div></section>`}
function renderClub(){const member=getStored('molliair-club-v2',null);return `<section class="club-hero"><div class="container club-layout"><div><span class="eyebrow" style="color:var(--green)">MOLLIAIR CLUB</span><h1 style="margin:12px 0 16px">Mehr von dem,<br>was du liebst.</h1><p style="max-width:510px;color:#bcd3df">Entdecke die Möglichkeiten von Molliair Club und halte deine Lieblingsziele und Reiseideen an einem Ort fest.</p><div style="margin-top:28px"><button data-action="club-scroll" class="btn btn-lime">Mitglied werden</button></div></div><div class="club-card"><div class="flex between align-center"><strong>molli<span class="member-logo">air</span></strong><span style="font-size:12px;letter-spacing:.16em">CLUB</span></div><div><div class="member-code">${member?E(member.number):'•••• •••• ••••'}</div><p style="font-size:11px;color:#c1d5df;margin-top:11px">${member?E(member.name):'DEIN NAME'}</p></div></div></div></section><div class="page-main"><div class="container"><div class="info-3"><div class="info-card"><div class="icon-box">${icon('heart')}</div><h3>Lieblingsziele merken</h3><p>Halte fest, wohin du als Nächstes reisen möchtest.</p></div><div class="info-card"><div class="icon-box">${icon('ticket')}</div><h3>Reisen im Blick</h3><p>Deine gespeicherten Reisepläne in einer Übersicht.</p></div><div class="info-card"><div class="icon-box">${icon('star')}</div><h3>Einfach verbunden</h3><p>Ein gemeinsamer Markenauftritt für Molliair und Molliair City.</p></div></div><div id="clubForm" class="panel" style="margin-top:38px;max-width:680px"><h2 style="font-size:27px">${member?'Deine Molliair Club Karte':'Jetzt dem Club beitreten'}</h2>${member?`<p class="muted">Mitgliedschaft in diesem Browser gespeichert für ${E(member.name)}.</p><div class="booking-code">${E(member.number)}</div><br><button class="btn btn-soft" data-action="club-leave">Lokales Profil löschen</button>`:`<form id="clubSignup"><p class="muted small" style="margin:11px 0 20px">Erstelle dein lokales Mitgliedsprofil für die Molliair Website.</p><div class="form-grid"><div class="form-field"><label>Vor- und Nachname</label><input name="name" required minlength="3" placeholder="Dein Name"></div><div class="form-field"><label>E-Mail-Adresse</label><input type="email" name="email" required placeholder="name@beispiel.de"></div></div><button class="btn btn-lime" style="margin-top:18px" type="submit">Profil erstellen ${icon('arrow')}</button><p class="note" style="margin-top:12px">Es wird kein externes Kundenkonto angelegt. Dein Profil bleibt lokal auf diesem Gerät.</p></form>`}</div></div></div>`}
function renderCity(){return pageHero('Molliair City','Regionale Verbindungen. Ein gemeinsames Drehkreuz. Noch mehr Möglichkeiten.',true)+`<section class="page-main"><div class="container"><div class="promo-banner"><div class="promo-content"><span class="eyebrow">EINE AIRLINE DER MOLLIAIR GROUP</span><h2>Gemeinsam weiterkommen.</h2><p>Molliair City übernimmt im geplanten Ausbau einen Teil der regionalen Zubringerflüge und verbindet unsere Nachbarregionen mit dem internationalen Drehkreuz Mollicity.</p>${button('Unser Streckennetz','#/network','lime')}</div><div class="promo-photo"></div></div><div class="info-3" style="margin-top:24px"><div class="info-card"><span class="eyebrow">01</span><h3 style="margin-top:12px">Mollicity als Zentrum</h3><p>Alle City-Verbindungen sollen möglichst gut auf internationale Abflüge und Ankünfte abgestimmt werden.</p></div><div class="info-card"><span class="eyebrow">02</span><h3 style="margin-top:12px">Embraer E190-E2</h3><p>Langfristig werden zwei E190-E2 in der City-Flotte vorgesehen, mit jeweils 106 Sitzen.</p></div><div class="info-card"><span class="eyebrow">03</span><h3 style="margin-top:12px">Eine gemeinsame Reise</h3><p>Vereinfachte Verbindungssuche und ein abgestimmtes Marken- und Tarifsystem innerhalb der Gruppe.</p></div></div><div class="panel" style="margin-top:32px"><span class="eyebrow">REGIONALE ANBINDUNG</span><h2 style="font-size:26px;margin:8px 0 14px">Die geplanten City-Destinationen</h2><div class="list-grid">${[['Molliburg','MBG','Täglich'],['Stachelcity','STC','6× wöchentlich'],['Miastadt','MST','5× wöchentlich 2030'],['Mollihausen','MHH','2× wöchentlich']].map(x=>`<div class="route-card"><div><div class="route-city">${x[0]}</div><div class="route-country">${x[1]} · ${x[2]}</div></div><a href="#/destination/${x[1]}" class="btn btn-soft btn-sm">Mehr →</a></div>`).join('')}</div><p class="note" style="margin-top:19px">Die Betriebsaufnahme und der Transfer von Strecken an Molliair City stehen im Rahmen des ARG-Ausbauplans.</p></div></div></section>`}
function renderAbout(){return pageHero('Über Molliair','Unsere Heimat ist Mollicity. Unser Horizont reicht weit darüber hinaus.',true)+`<div class="page-main"><div class="container grid-sidebar"><div class="prose"><span class="eyebrow">WER WIR SIND</span><h2 style="margin:11px 0 18px">Verbunden mit Molliland.<br>Offen für die Welt.</h2><p>Molliair verbindet Mollicity mit Städten und Regionen in Molliland, Stachelland, Mialand und internationalen Destinationen. Das Drehkreuz Mollicity steht im Mittelpunkt unseres Netzwerks und ermöglicht Reisen weit über die Hauptstadt hinaus.</p><p>Nach dem Zusammenschluss mit Aurelia Regional Group (ARG) konzentriert sich die Gruppe auf ein zuverlässiges Netz, moderne Flugzeuge und eine stärkere Vernetzung der regionalen Zubringer.</p><h3>Unser Drehkreuz: Mollicity</h3><p>Mollicity ist die Heimatbasis der Molliair-Flotte. Hier treffen internationale Verbindungen mit regionalen Zubringern zusammen. Mit der geplanten Airline Molliair City soll die Anschlussqualität weiter verbessert werden.</p><h3>Unsere nächsten Schritte</h3><p>Die Gruppe plant zusätzliche Investitionen von 100 Millionen Euro, eine Flottenerweiterung auf insgesamt sieben Embraer E2 bis 2030 und eine Fokussierung auf die Basis Mollicity. Der regionale Standort Molliburg bleibt dabei wichtig, erhält aber keine größere eigenständige Flugzeugbasis.</p><h3>Das Molliair-Netz</h3><p>Im Sommerflugplan 2027 sind 32 wöchentliche Molliair-Abflüge ab Mollicity vorgesehen. Internationale Kernziele sind unter anderem die USA, Brasilien und Madagaskar; zusätzlich stärken regionale Flüge das Netz.</p><div class="chip-links"><a href="#/fleet">Unsere Flotte</a><a href="#/city">Molliair City</a><a href="#/news">Pressemitteilungen</a><a href="#/network">Streckennetz</a></div></div><aside><div class="panel side-sticky"><span class="eyebrow">MOLLIAIR GROUP</span><h3 style="margin:12px 0 18px">Aurelia Regional Group</h3><div class="sum-row"><span>Heimatflughafen</span><strong>MOL</strong></div><div class="sum-row"><span>Flotte 2030 geplant</span><strong>7 E2</strong></div><div class="sum-row"><span>Mitglied der Gruppe</span><strong>Molliair City</strong></div><div class="sum-row"><span>Fokusstandort</span><strong>Molliburg</strong></div></div></aside></div></div>`}
function renderNews(){const news=[['23.11.2026','ARG übernimmt Molliair und stellt neue Wachstumsstrategie vor','Der Konzern bündelt die Flottenplanung in Mollicity und richtet die Struktur für den Ausbau neu aus.'],['23.11.2026','100 Millionen Euro für die nächste Entwicklungsphase','Molliair erhält im Rahmen des ARG-Programms eine langfristige Finanzierungsperspektive.'],['Sommer 2027','Neue Verbindung nach Miastadt geplant','Die Nachbarinsel Mialand wird im Sommerflugplan dreimal wöchentlich mit der E190-E2 eingebunden.'],['Ausblick 2030','Molliair City soll regionale Zubringer übernehmen','Zwei E190-E2 stehen in der Planung für die City-Flotte.']];return pageHero('Newsroom','Aktuelle Meldungen und Einblicke aus der Molliair Group.')+`<div class="page-main"><div class="container">${sectionHeading('AKTUELLES','Neuigkeiten aus der Gruppe','Entwicklungen rund um unser Streckennetz, die Flotte und Mollicity.')}<div class="news-list">${news.map(x=>`<article class="news-card"><span class="eyebrow">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><span class="tag">Molliair Group</span></article>`).join('')}</div></div></div>`}
const FAQ=[['Wann öffnet der Check-in?','Der Online Check-in ist grundsätzlich ab 24 Stunden vor der geplanten Abflugzeit vorgesehen. In der Website kannst du den Ablauf mit einem lokal gespeicherten Reiseplan nachvollziehen.'],['Wie viel Gepäck ist enthalten?','LIGHT enthält 8 kg Handgepäck, CLASSIC zusätzlich 23 kg Aufgabegepäck, FLEX ebenfalls 23 kg sowie zusätzliche Flexibilität. BUSINESS sieht 32 kg Aufgabegepäck vor.'],['Wie finde ich Verbindungen mit Umstieg?','Gib einen Start- und einen Zielflughafen ein. Die Suche berücksichtigt Direktflüge und geeignete Verbindungen über Mollicity, sofern sie zu den Flugzeiten passen.'],['Kann ich meine Reise ändern?','Einen gespeicherten Reiseplan kannst du unter „Meine Buchung“ öffnen und Zusatzgepäck lokal anpassen oder den Reiseplan stornieren.'],['Wo steht meine Buchungsnummer?','Nach dem Speichern erhältst du einen Code, der auf dieser Website zur lokalen Wiedererkennung des Reiseplans dient.'],['Gibt es eine Business Class?','Auf ausgewählten internationalen Strecken werden Business-Tarife angezeigt. Die genaue Auswahl hängt von der Verbindung ab.'],['Was ist Molliair City?','Molliair City ist als eigene regionale Tochterairline der Molliair-Gruppe geplant und soll Zubringerflüge für das Drehkreuz Mollicity übernehmen.']];
function renderHelp(){return pageHero('Hilfe & Kontakt','Antworten auf die wichtigsten Fragen rund um deine Reise.')+`<div class="page-main"><div class="container grid-sidebar"><div><div class="panel"><h2 style="font-size:28px;margin-bottom:18px">Häufig gestellte Fragen</h2>${FAQ.map(x=>`<details class="faq-row"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>Nachricht vorbereiten</h3><p class="muted small" style="margin:8px 0 19px">Formuliere deine Anfrage und kopiere sie für deine eigenen Unterlagen. Es erfolgt kein externer Versand.</p><form id="contactForm"><div class="form-grid"><div class="form-field"><label>Dein Name</label><input name="name" required placeholder="Vor- und Nachname"></div><div class="form-field"><label>E-Mail</label><input name="email" type="email" required placeholder="name@beispiel.de"></div></div><div class="form-field" style="margin:16px 0"><label>Deine Nachricht</label><textarea name="message" required placeholder="Wie können wir dir helfen?"></textarea></div><button class="btn btn-dark" type="submit">Anfrage kopieren ${icon('arrow')}</button></form></div></div><aside><div class="panel"><h3>Schnell zum Ziel</h3><div class="chip-links"><a href="#/manage">Meine Buchung</a><a href="#/checkin">Check-in</a><a href="#/baggage">Gepäck</a><a href="#/status">Flugplan</a></div></div></aside></div></div>`}
function renderLegal(){return pageHero('Rechtliches & Datenschutz','Informationen zur Nutzung dieser Webpräsenz.')+`<div class="page-main"><div class="container prose"><h3>Buchungsfunktion</h3><p>Diese Website ist eine interaktive Produktstudie für das Molliair-Projekt. Sie stellt keine rechtsverbindlichen Flugangebote bereit. Angezeigte Preise, Flugzeiten und Leistungen dienen der Darstellung des Buchungsablaufs. Es werden weder echte Tickets ausgestellt noch Zahlungen verarbeitet.</p><h3>Persönliche Daten</h3><p>Reisepläne, Club-Profile und weitere Eingaben werden im lokalen Speicher deines Browsers abgelegt. Ein Server zum Versand, zur Ticketierung oder zur Kundenverwaltung ist nicht verbunden. Bitte keine echten Zahlungsdaten eingeben.</p><h3>Flugstatus</h3><p>Die Flugstatus-Seite zeigt veröffentlichte Planzeiten innerhalb des Projektflugplans. Sie besitzt keine Anbindung an Flugverfolgung, Flughafenbetriebsdaten oder eine operative Airline-Datenbank.</p><h3>Bildmaterial</h3><p>Zur Gestaltung werden unabhängige Reisefotografien aus der Bildbibliothek Unsplash genutzt. Diese Bilder stellen keine konkreten Molliair-Flugzeuge oder -Flughäfen dar.</p><h3>Markenauftritt</h3><p>Molliair verfügt in diesem Projekt über ein eigenständiges visuelles Erscheinungsbild. Es handelt sich nicht um ein Angebot von Lufthansa oder airBaltic.</p></div></div>`}
function renderNetwork(){const y=STATE.networkYear,airport=STATE.networkAirport,al=STATE.networkAirline;let flights=C.networkFlights(D,y).filter(f=>al==='ARG'?['ML','MC'].includes(f.carrier):al==='all'||f.carrier===al);const coords=Object.fromEntries(D.airports.map(a=>[a.code,a]));let edges=new Map();for(const f of flights){const pair=[f.from,f.to].sort().join('–');if(!edges.has(pair))edges.set(pair,{from:f.from,to:f.to,carrier:f.carrier})}const used=new Set([...edges.values()].flatMap(x=>[x.from,x.to]));const fromHere=[...edges.values()].filter(x=>x.from===airport||x.to===airport).map(x=>({to:x.from===airport?x.to:x.from,...x}));const map=`<div class="network-map"><svg viewBox="0 0 1100 720" role="img" aria-label="Molliair Streckenkarte"><defs><linearGradient id="sea" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#bcdfdf"/><stop offset="1" stop-color="#e3f6f6"/></linearGradient><filter id="land-shadow"><feDropShadow dx="0" dy="8" stdDeviation="12" flood-color="#56888b" flood-opacity=".22"/></filter></defs><rect width="1100" height="720" fill="url(#sea)"/><g fill="#c5e4c1" stroke="#9ecba1" stroke-width="3" filter="url(#land-shadow)"><path d="M415 240Q490 168 598 203T729 310Q774 390 718 481T579 560Q468 529 422 433T415 240Z"/><path d="M846 118Q907 85 997 128T1028 278Q985 354 897 313T846 118Z"/><path d="M918 455Q972 428 1034 465T1048 566Q1014 621 952 593T918 455Z"/><path d="M160 395Q198 375 244 407T264 481Q223 514 173 478Z"/></g><g fill="#79adac" opacity=".45"><circle cx="814" cy="493" r="6"/><circle cx="771" cy="180" r="4"/><circle cx="386" cy="323" r="5"/></g><text x="563" y="292" fill="#5a9296" font-size="22" font-weight="800" text-anchor="middle">MOLLILAND</text><text x="936" y="192" fill="#5a9296" font-size="19" font-weight="800" text-anchor="middle">STACHELLAND</text><text x="988" y="465" fill="#5a9296" font-size="14" font-weight="800" text-anchor="middle">MIALAND</text>${[...edges.values()].map(x=>{let a=coords[x.from],b=coords[x.to];let act=x.from===airport||x.to===airport;const cx=(a.x+b.x)/2,cy=(a.y+b.y)/2-28;return `<path class="route-line ${act?'highlight':''}" d="M${a.x} ${a.y}Q${cx} ${cy} ${b.x} ${b.y}"/>`}).join('')}${[...used].filter(x=>coords[x]).map(c=>{let a=coords[c];return `<g class="airport-pin ${airport===c?'active':''}" data-action="network-pin" data-airport="${c}" role="button" tabindex="0"><circle cx="${a.x}" cy="${a.y}" r="8"/><text x="${a.x+11}" y="${a.y-13}">${c}</text></g>`}).join('')}</svg></div>`;return pageHero('Unser Streckennetz','Entdecke Verbindungen ab Mollicity und unseren regionalen Standorten.')+`<div class="page-main"><div class="container"><div class="filter-row"><label class="small">Netzstand <select id="networkYear"><option value="2026" ${y===2026?'selected':''}>Sommer 2026</option><option value="2027" ${y===2027?'selected':''}>Sommer 2027</option><option value="2030" ${y===2030?'selected':''}>Ausbau 2030</option></select></label><label class="small">Fluggesellschaft <select id="networkAirline"><option value="ARG" ${al==='ARG'?'selected':''}>Molliair Group</option><option value="all" ${al==='all'?'selected':''}>Alle Airlines</option>${D.airlines.map(a=>`<option value="${a.id}" ${al===a.id?'selected':''}>${E(a.name)}</option>`).join('')}</select></label></div><div class="network-layout">${map}<div class="network-sidebar"><div class="eyebrow">FLUGHAFEN</div><h3 style="margin:8px 0">${E(routeLabel(airport))}</h3><p class="muted small">${fromHere.length} direkte Verbindungen im ausgewählten Netz</p><div class="divider"></div>${fromHere.length?fromHere.map(x=>`<button data-action="network-pin" data-airport="${E(x.to)}"><span>${E(codeName(x.to))} <small>(${x.to})</small></span><span>→</span></button>`).join(''):`<p class="muted small">Keine weiteren Strecken. Wähle einen anderen Flughafen auf der Karte.</p>`}</div></div><p class="note" style="margin-top:17px">Die Karte zeigt die in der Planung hinterlegten Flugverbindungen; die Verfügbarkeit nach Datum wird in der Flugsuche geprüft.</p><div style="margin-top:24px">${button('Flüge suchen','#/booking','lime')}</div></div></div>`}
const RENDERERS={home:renderHome,booking:renderBooking,results:renderResults,fares:renderFares,passengers:renderPassengers,extras:renderExtras,review:renderReview,success:renderSuccess,destinations:renderDestinations,offers:renderOffers,manage:renderManage,checkin:renderCheckin,status:renderStatus,baggage:renderBaggage,experience:renderExperience,city:renderCity,fleet:renderFleet,club:renderClub,about:renderAbout,news:renderNews,help:renderHelp,legal:renderLegal,network:renderNetwork};
function render(){let {page,param}=ROUTE(); if(!RENDERERS[page]&&page!=='destination')page='home';try{$('app').innerHTML=page==='destination'?renderDestination(param):RENDERERS[page]();document.title=(NAV[page]||codeName(param)||'Molliair')+' | Molliair';document.body.classList.toggle('page-is-home',page==='home');$('mobileDrawer').hidden=true;$('mobileMenuToggle').setAttribute('aria-expanded','false')}catch(err){console.error('Render issue',err);$('app').innerHTML=`<div class="container" style="padding:80px 0"><h2>Diese Seite konnte nicht angezeigt werden.</h2><p class="muted" style="margin:18px 0">Bitte lade die Website neu oder gehe zurück zur Startseite.</p>${button('Startseite','#/home','lime')}</div>`}}
function readSearchForm(el){if(!el)return false;const f=STATE.form;f.from=el.querySelector('[name=from]').value;f.to=el.querySelector('[name=to]').value;f.dateOut=el.querySelector('[name=dateOut]').value;f.dateIn=el.querySelector('[name=dateIn]').value||C.dateShift(f.dateOut,7);f.trip=el.querySelector('[name=trip]:checked')?.value||'round';if(f.from===f.to){showToast('Bitte wähle unterschiedliche Start- und Zielflughäfen.');return false}if(!C.parseDay(f.dateOut)||f.dateOut<'2026-11-23'||f.dateOut>'2027-10-31'){showToast('Bitte wähle einen verfügbaren Reisetag.');return false}if(f.trip==='round'&&(!C.parseDay(f.dateIn)||f.dateIn<f.dateOut)){showToast('Der Rückflug darf nicht vor dem Hinflug liegen.');return false}return true}
function resetBooking(){STATE.booking={out:null,back:null,fare:'CLASSIC',people:[],email:'',phone:'',extras:{bags:0,seats:0,meals:0,priority:false},selectedSeats:[],agree:false};STATE.resultPhase='out';STATE.sort='recommended';STATE.connectionFilter='all'}
function bookingSearch(){if(!readSearchForm($('flightSearchForm')))return;resetBooking();STATE.widget='book';go('results')}
function chooseResult(id,phase){const f=STATE.form;const isReturn=phase==='return',from=isReturn?f.to:f.from,to=isReturn?f.from:f.to,date=isReturn?f.dateIn:f.dateOut;const found=C.search(D,from,to,date,{maxStops:STATE.connectionFilter==='direct'?0:STATE.connectionFilter==='one'?1:2,airlineScope:STATE.airlineScope}).find(x=>x.id===id);if(!found){showToast('Der gewählte Flug ist nicht mehr im Flugplan.');return}if(hasOtherOperators(found))STATE.booking.fare='CLASSIC';if(isReturn){STATE.booking.back=found;go('fares')}else{STATE.booking.out=found;if(f.trip==='round'&&f.dateIn<=found.arriveDate)f.dateIn=C.dateShift(found.arriveDate,1);if(f.trip==='one'){STATE.booking.back=null;go('fares')}else{STATE.resultPhase='return';render();window.scrollTo(0,0)}}}
function updateStoredReservation(rec){let arr=bookings();let i=arr.findIndex(r=>r.code===rec.code);if(i<0)return;arr[i]=rec;save('molliair-reservations-v2',arr)}
function firstAvailableDay(to){let d='2027-05-10';for(let i=0;i<14;i++){if(C.search(D,'MOL',to,d).some(x=>x.stops===0))return d;d=C.dateShift(d,1)}return '2027-05-14'}
function applyOffer(to){STATE.form.from='MOL';STATE.form.to=to;STATE.form.dateOut=firstAvailableDay(to);STATE.form.dateIn=C.dateShift(STATE.form.dateOut,7);STATE.form.trip='round';resetBooking();go('results')}
function openManage(form,which){const rec=findReservation(form);if(!rec){showToast('Kein lokaler Reiseplan mit diesen Angaben gefunden.');return}if(which==='checkin'){STATE.checkinBooking=rec;go('checkin')}else{STATE.managed=rec;go('manage')}}
function submitForm(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;
 if(form.id==='flightSearchForm'){e.preventDefault();bookingSearch();return}
 if(['widgetLookup','lookupForm'].includes(form.id)){e.preventDefault();openManage(new FormData(form),form.dataset.kind||'manage');return}
 if(form.id==='passengerForm'){e.preventDefault();const fd=new FormData(form),p=C.passengersCount(STATE.form);STATE.booking.people=[];for(let i=0;i<p.count;i++){let first=String(fd.get('first'+i)||'').trim(),last=String(fd.get('last'+i)||'').trim(),birth=String(fd.get('birth'+i)||'');if(!first||!last||!birth){showToast('Bitte fülle alle Pflichtfelder aus.');return}STATE.booking.people.push({first,last,birth,gender:fd.get('gender'+i)||''})}STATE.booking.email=String(fd.get('email')||'').trim();STATE.booking.phone=String(fd.get('phone')||'').trim();go('extras');return}
 if(form.id==='statusForm'||form.id==='statusQuickForm'){e.preventDefault();let fd=new FormData(form);STATE.statusFlight=String(fd.get('flightno')||'').trim();STATE.statusDate=String(fd.get('date')||STATE.form.dateOut);go('status');return}
 if(form.id==='clubSignup'){e.preventDefault();let fd=new FormData(form),name=String(fd.get('name')||'').trim(),email=String(fd.get('email')||'').trim();if(name.length<3||!email.includes('@')){showToast('Bitte prüfe deine Angaben.');return}let num='ML'+Math.floor(10000000+Math.random()*89999999);save('molliair-club-v2',{name,email,number:num});render();showToast('Dein Club-Profil wurde auf diesem Gerät gespeichert.');return}
 if(form.id==='newsletterForm'){e.preventDefault();let email=new FormData(form).get('email');save('molliair-updates-v2',{email,date:new Date().toISOString()});showToast('E-Mail-Adresse als lokale Präferenz gespeichert. Es wurde keine Nachricht versendet.');form.reset();return}
 if(form.id==='contactForm'){e.preventDefault();let fd=new FormData(form),message=`Molliair Kontaktanfrage\nName: ${fd.get('name')}\nE-Mail: ${fd.get('email')}\n\n${fd.get('message')}`;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(message).then(()=>showToast('Anfrage in die Zwischenablage kopiert.')).catch(()=>showToast('Kopieren nicht möglich. Bitte Text manuell auswählen.'));else showToast('Zwischenablage ist hier nicht verfügbar.');return}
}
function changeInput(e){const el=e.target;
 if(el.name==='trip'&&el.form?.id==='flightSearchForm'){STATE.form.trip=el.value;let date=$('date-in');if(date)date.disabled=el.value==='one';return}
 if(el.id==='airlineScope'){STATE.airlineScope=el.value;render();return}
 if(el.id==='sortFlights'){STATE.sort=el.value;render();return}
 if(el.id==='filterConnections'){STATE.connectionFilter=el.value;render();return}
 if(el.id==='networkYear'){STATE.networkYear=Number(el.value);render();return}
 if(el.id==='networkAirline'){STATE.networkAirline=el.value;render();return}
 if(el.id==='bookingAgree'){STATE.booking.agree=el.checked;let btn=document.querySelector('[data-action="confirm-booking"]');if(btn)btn.disabled=!el.checked;return}
 if(el.dataset.action==='extra-check'){if(bookingHasOtherOperators()){showToast('Partner-Zusatzleistungen sind in dieser Vorschau nicht buchbar.');render();return}let id=el.dataset.extra;if(id==='priority')STATE.booking.extras.priority=el.checked;else STATE.booking.extras[id]=el.checked?1:0;render();return}
 if(['from','to','dateOut','dateIn'].includes(el.name)&&el.form?.id==='flightSearchForm')STATE.form[el.name]=el.value;
}
function actionClick(e){const btn=e.target.closest('[data-action]');if(!btn)return;const act=btn.dataset.action;
 if(act==='widget-tab'){STATE.widget=btn.dataset.tab;STATE.popup=false;render();return}
 if(act==='swap'){const from=$('from-select'),to=$('to-select');if(from&&to){let a=from.value;from.value=to.value;to.value=a;STATE.form.from=from.value;STATE.form.to=to.value}return}
 if(act==='passengers-pop'){STATE.popup=!STATE.popup;render();return}
 if(act==='close-passengers'){STATE.popup=false;render();return}
 if(act==='counter'){const key=btn.dataset.counter,delta=Number(btn.dataset.delta),f=STATE.form;let n=f[key]+delta;if(key==='adults')f.adults=Math.min(9,Math.max(1,n));if(key==='children')f.children=Math.min(8,Math.max(0,n));if(key==='infants')f.infants=Math.min(f.adults,Math.max(0,n));if(f.adults+f.children>9){f.children=Math.max(0,9-f.adults)}STATE.popup=true;render();return}
 if(act==='offer-search'){applyOffer(btn.dataset.dest);return}
 if(act==='destination-filter'){STATE.destinationRegion=btn.dataset.filter;render();return}
 if(act==='change-search-date'){let key=btn.dataset.phase==='out'?'dateOut':'dateIn';let d=btn.dataset.date;if(d<'2026-11-23'||d>'2027-10-31')return;STATE.form[key]=d;if(key==='dateOut'&&STATE.form.dateIn<d)STATE.form.dateIn=C.dateShift(d,7);if(key==='dateOut')STATE.booking.out=null;else STATE.booking.back=null;render();return}
 if(act==='choose-flight'){chooseResult(btn.dataset.id,btn.dataset.phase);return}
 if(act==='choose-fare'){STATE.booking.fare=btn.dataset.fare;render();return}
 if(act==='continue-fare'){go('passengers');return}
 if(act==='seat'){if(bookingHasOtherOperators())return;let list=STATE.booking.selectedSeats,s=btn.dataset.seat,i=list.indexOf(s),limit=C.passengersCount(STATE.form).count;if(i>=0)list.splice(i,1);else if(list.length<limit)list.push(s);else{showToast('Es kann nur ein Sitzplatz pro Reisendem ausgewählt werden.');return}STATE.booking.extras.seats=list.length;render();return}
 if(act==='continue-extras'){go('review');return}
 if(act==='confirm-booking'){if(!STATE.booking.agree||!STATE.booking.out||!STATE.booking.people.length){showToast('Bitte prüfe deine Reisedaten und den Hinweis.');return}let rec=bookingRecord();save('molliair-reservations-v2',[rec,...bookings()].slice(0,25));STATE.managed=rec;go('success');return}
 if(act==='print'){window.print();return}
 if(act==='manage-bag'){let b=STATE.managed;if(!b||b.cancelled)return;b.extras.bags=b.extras.bags?0:1;b.total=C.quote([b.out,b.back],b.form,b.fare,b.extras).total;updateStoredReservation(b);render();showToast('Zusatzgepäck wurde im lokalen Reiseplan geändert.');return}
 if(act==='manage-cancel'){let b=STATE.managed;if(!b||b.cancelled)return;if(window.confirm('Diesen gespeicherten Reiseplan wirklich stornieren?')){b.cancelled=true;updateStoredReservation(b);render();showToast('Reiseplan lokal storniert.')}return}
 if(act==='checkin-confirm'){let b=STATE.checkinBooking;if(!b)return;let t=C.parseDay(b.form.dateOut)?.getTime(),now=Date.now();if(!t||now<t-24*3600*1000||now>=t+4*3600*1000){showToast('Das Check-in-Zeitfenster ist nicht geöffnet.');return}b.checkedIn=true;updateStoredReservation(b);render();showToast('Check-in-Vermerk lokal gespeichert.');return}
 if(act==='network-pin'){STATE.networkAirport=btn.dataset.airport;render();return}
 if(act==='club-leave'){localStorage.removeItem('molliair-club-v2');render();showToast('Das lokale Club-Profil wurde gelöscht.');return}
 if(act==='club-scroll'){$('clubForm')?.scrollIntoView({behavior:'smooth',block:'start'});return}
}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
document.addEventListener('click',actionClick);document.addEventListener('submit',submitForm);document.addEventListener('change',changeInput);
$('mobileMenuToggle').addEventListener('click',()=>{let d=$('mobileDrawer'),hidden=!d.hidden;d.hidden=hidden;$('mobileMenuToggle').setAttribute('aria-expanded',String(!hidden))});$('mobileDrawer').addEventListener('click',e=>{if(e.target.closest('a'))$('mobileDrawer').hidden=true});
$('openSearchBtn').addEventListener('click',()=>{STATE.widget='book';go('booking')});$('languageBtn').addEventListener('click',()=>showToast('Deutsch · EUR – derzeitige Sprache und Währung.'));
window.MolliairApp={STATE,go,render};render();
})();